// Summarise what is waiting for a human. This workflow never promotes
// anything: promotion runs both gates in the Python service, and doing it
// from here would skip the reproduction check.
const items = $input.all().map(i => i.json).flat();
if (!items.length) return [];
const byReason = {};
for (const s of items) {
  byReason[s.failure_reason || 'UNKNOWN'] = (byReason[s.failure_reason || 'UNKNOWN'] || 0) + 1;
}
return [{ json: {
  waiting: items.length,
  by_failure_reason: byReason,
  review_url: 'http://localhost:8000/admin/solutions?status=CANDIDATE',
  oldest: items[items.length - 1]?.created_at ?? null
} }];
